"""Glossário "Entenda o Mercado" — termos da V1 (revisão de acentuação e digitação)
mais "Base 100", que aparece no mockup da V2.

Categorias exibidas como chips: Mercado, Risco, Renda Fixa, Câmbio, Cripto, Indicadores.
(A V1 tinha o filtro 'Cambio' sem acento e os termos com 'Câmbio', o que deixava o filtro vazio.)
"""

CATEGORIES = ["Mercado", "Risco", "Renda Fixa", "Câmbio", "Cripto", "Indicadores"]

GLOSSARY = [
    {"term": "Ação", "category": "Mercado",
     "definition": "Uma ação é um pedaço de uma empresa. Quem compra uma ação da Petrobras vira sócio de uma fração dela e tem direito a uma parte dos lucros (dividendos) e da valorização do negócio.",
     "example": "Se a Petrobras sobe 10% e você tem R$ 1.000 investidos, seu patrimônio vai para R$ 1.100."},
    {"term": "Ibovespa (IBOV)", "category": "Mercado",
     "definition": "O Ibovespa é o principal índice da bolsa brasileira (B3). Reúne as ações mais negociadas do país e funciona como um termômetro da economia. Quando ele sobe, em geral as empresas do Brasil estão indo bem.",
     "example": "Ibovespa em 130.000 pontos contra 120.000 = crescimento de cerca de 8% no período."},
    {"term": "S&P 500", "category": "Mercado",
     "definition": "O S&P 500 é o principal índice dos EUA, composto pelas 500 maiores empresas americanas, como Apple, Microsoft, Google e Amazon. É o maior termômetro da economia global.",
     "example": "Uma queda de 5% no S&P 500 costuma puxar a bolsa brasileira para baixo também."},
    {"term": "Dow Jones", "category": "Mercado",
     "definition": "O Dow Jones é o índice mais antigo dos EUA, formado por 30 grandes empresas tradicionais americanas. É mais conservador que o S&P 500.",
     "example": "Boeing, Coca-Cola, Goldman Sachs e Apple fazem parte do Dow Jones."},
    {"term": "Base 100", "category": "Mercado",
     "definition": "Forma de comparar ativos diferentes partindo do mesmo ponto inicial. O primeiro dia do período vale 100 para todos; depois, cada linha mostra quanto aquele ativo subiu ou caiu desde então.",
     "example": "Se uma ação está em 112 no gráfico base 100, ela subiu 12% no período, seja qual for o preço dela."},
    {"term": "Dividendo", "category": "Mercado",
     "definition": "Dividendos são a parte do lucro que a empresa distribui aos acionistas. Funcionam como uma renda passiva: você recebe periodicamente sem precisar vender a ação.",
     "example": "Com R$ 10.000 investidos e dividend yield de 8% ao ano, você recebe cerca de R$ 800 por ano."},
    {"term": "Liquidez", "category": "Mercado",
     "definition": "Liquidez é a facilidade de comprar ou vender um ativo rapidamente sem perder valor. Ações de grandes empresas têm alta liquidez; imóveis têm baixa liquidez.",
     "example": "Uma ação que negocia R$ 500 milhões por dia tem altíssima liquidez."},
    {"term": "Volatilidade", "category": "Risco",
     "definition": "Volatilidade mede o quanto o preço de um ativo oscila ao longo do tempo. Alta volatilidade = sobe e desce muito; baixa volatilidade = mais estável. Aqui ela é o desvio-padrão dos retornos diários, anualizado.",
     "example": "O Bitcoin pode ter volatilidade de 80% ao ano. O Tesouro Selic tem volatilidade próxima de zero."},
    {"term": "Retorno", "category": "Risco",
     "definition": "Retorno é o quanto um investimento cresceu (ou caiu) em um período. Nos cards, o retorno é sempre o do período selecionado.",
     "example": "Comprou a R$ 50 e o preço foi para R$ 60: retorno de 20%."},
    {"term": "Risco x retorno", "category": "Risco",
     "definition": "Na renda variável, maior risco geralmente vem com maior potencial de retorno. O gráfico de risco x retorno mostra essa relação para cada ativo da sua carteira.",
     "example": "Bitcoin: alto risco e alto retorno histórico. Tesouro Selic: baixo risco e retorno menor."},
    {"term": "Diversificação", "category": "Risco",
     "definition": "Diversificar é não colocar todos os ovos na mesma cesta. Misturar ações brasileiras, americanas, cripto e renda fixa reduz o risco total da carteira.",
     "example": "Uma carteira com 20 ativos tem risco bem menor do que uma carteira 100% em uma só empresa."},
    {"term": "Selic", "category": "Renda Fixa",
     "definition": "A Selic é a taxa básica de juros do Brasil, definida pelo Banco Central a cada 45 dias. Ela influencia o rendimento da renda fixa, o custo do crédito e o comportamento da bolsa. Selic alta = renda fixa mais atrativa.",
     "example": "Com a Selic a 13,75% ao ano, quem investe no Tesouro Selic ganha cerca de 13,75% ao ano com baixíssimo risco."},
    {"term": "CDB", "category": "Renda Fixa",
     "definition": "O CDB (Certificado de Depósito Bancário) é um título de renda fixa emitido pelos bancos. Você empresta dinheiro ao banco e recebe juros em troca. O rendimento pode ser prefixado, pós-fixado (em geral atrelado ao CDI) ou indexado à inflação.",
     "example": "Um CDB de 110% do CDI rende 11% ao ano se o CDI for 10%. Se o CDI subir para 12%, o rendimento sobe para 13,2%."},
    {"term": "CDI", "category": "Renda Fixa",
     "definition": "O CDI (Certificado de Depósito Interbancário) é a taxa que os bancos cobram entre si. Na prática anda colado à Selic e é a referência de quase toda a renda fixa brasileira.",
     "example": "Um CDB que rende 110% do CDI é melhor que um que rende 90% do CDI."},
    {"term": "IPCA", "category": "Renda Fixa",
     "definition": "O IPCA é o índice oficial de inflação do Brasil. Um bom investimento rende acima do IPCA; caso contrário, o dinheiro perde poder de compra mesmo rendendo.",
     "example": "IPCA de 5% ao ano e investimento que rendeu 4%: você perdeu 1% de poder de compra."},
    {"term": "Tesouro Direto", "category": "Renda Fixa",
     "definition": "O Tesouro Direto é o programa do governo que permite a pessoas físicas comprar títulos públicos pela internet, com opções prefixadas, pós-fixadas e indexadas à inflação.",
     "example": "Tesouro IPCA+ 2035: paga IPCA + uma taxa fixa, garantindo rendimento acima da inflação."},
    {"term": "Spread", "category": "Câmbio",
     "definition": "Spread é a diferença entre o preço de compra e o de venda — por exemplo, entre o que o banco paga para captar dinheiro e o que cobra para emprestá-lo.",
     "example": "O banco capta pagando 10% ao ano e empresta cobrando 40%: os 30 pontos de diferença são o spread."},
    {"term": "Câmbio", "category": "Câmbio",
     "definition": "Câmbio é a taxa de conversão entre duas moedas. Dólar a R$ 5,20 significa que você precisa de R$ 5,20 para comprar US$ 1,00. Ele sobe e desce conforme a economia, os juros e o fluxo de capital.",
     "example": "Dólar subindo = importados mais caros e exportações brasileiras mais competitivas."},
    {"term": "Dólar comercial", "category": "Câmbio",
     "definition": "O dólar comercial é a taxa usada em importações, exportações e remessas. É diferente do dólar turismo, que inclui o spread das casas de câmbio.",
     "example": "Dólar comercial a R$ 5,20 e dólar turismo a R$ 5,60: a diferença é o custo da operação."},
    {"term": "Bitcoin (BTC)", "category": "Cripto",
     "definition": "O Bitcoin é a primeira e maior criptomoeda do mundo, criada em 2009. Funciona em uma rede descentralizada (blockchain) e tem emissão limitada a 21 milhões de unidades. É chamado de ouro digital.",
     "example": "Em 2020 o BTC valia cerca de US$ 10.000; em 2021 chegou a US$ 69.000. Alta volatilidade."},
    {"term": "Ethereum (ETH)", "category": "Cripto",
     "definition": "O Ethereum é a segunda maior criptomoeda e a principal plataforma para contratos inteligentes e aplicações descentralizadas (DeFi, NFTs).",
     "example": "Criar um NFT ou usar um aplicativo DeFi consome ETH como taxa."},
    {"term": "Blockchain", "category": "Cripto",
     "definition": "Blockchain é a tecnologia por trás das criptomoedas: um banco de dados distribuído, copiado em milhares de computadores, que torna as transações praticamente impossíveis de falsificar.",
     "example": "Uma transação de Bitcoin fica registrada permanentemente em todos os nós da rede."},
    {"term": "P/L (preço/lucro)", "category": "Indicadores",
     "definition": "O P/L indica quantos anos de lucro você pagaria pela empresa ao preço atual. P/L muito alto pode indicar ação cara; P/L baixo pode ser uma pechincha — ou uma armadilha.",
     "example": "Ação a R$ 50 com lucro por ação de R$ 5 tem P/L de 10: seriam 10 anos de lucro para recuperar o valor pago."},
    {"term": "Dividend yield", "category": "Indicadores",
     "definition": "O dividend yield mostra quanto a empresa paga em dividendos em relação ao preço da ação, em porcentagem ao ano.",
     "example": "Ação a R$ 100 que paga R$ 10 por ano em dividendos tem dividend yield de 10% ao ano."},
    {"term": "Market cap (valor de mercado)", "category": "Indicadores",
     "definition": "O market cap é o valor total de uma empresa na bolsa: preço da ação × número de ações. Serve para comparar o tamanho das empresas.",
     "example": "Ação a R$ 50 × 1 bilhão de ações = valor de mercado de R$ 50 bilhões."},
]

assert all(t["category"] in CATEGORIES for t in GLOSSARY)
